import{_ as o,o as t,c as i,a3 as a}from"./chunks/framework.BveOjhN0.js";const h=JSON.parse('{"title":"Tenant API v1 — Opportunities","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Opportunities | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-opportunities"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Opportunities | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-opportunities"}]]},"headers":[],"relativePath":"api/tenant-v1-opportunities.md","filePath":"api/tenant-v1-opportunities.md","lastUpdated":1785453370000}'),d={name:"api/tenant-v1-opportunities.md"};function n(s,e,r,p,c,u){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-api-v1-—-opportunities" tabindex="-1">Tenant API v1 — Opportunities <a class="header-anchor" href="#tenant-api-v1-—-opportunities" aria-label="Permalink to &quot;Tenant API v1 — Opportunities&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>verified</code>, <code>module:opportunities</code>, plus permission middleware / policies.</p><p>Assignee scoping: without <code>opportunities.assign</code> (and not superadmin), list/stats/board/view/update only include opportunities where <code>assigned_to</code> is the current user.</p><h2 id="stages" tabindex="-1">Stages <a class="header-anchor" href="#stages" aria-label="Permalink to &quot;Stages&quot;">​</a></h2><h3 id="get-opportunity-stages" tabindex="-1">GET <code>/opportunity-stages</code> <a class="header-anchor" href="#get-opportunity-stages" aria-label="Permalink to &quot;GET `/opportunity-stages`&quot;">​</a></h3><p>Permission: <code>opportunities.view</code>. Returns seeded pipeline stages for the workspace (Prospecting … Won / Lost), ensuring defaults exist if the tenant has none.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-opportunities-stats" tabindex="-1">GET <code>/opportunities/stats</code> <a class="header-anchor" href="#get-opportunities-stats" aria-label="Permalink to &quot;GET `/opportunities/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Payload includes:</p><p><code>total_opportunities</code>, <code>my_opportunities</code>, <code>open</code>, <code>won</code>, <code>lost</code>, <code>pipeline_value</code>, <code>weighted_pipeline_value</code>, <code>won_value</code>, <code>conversion_rate</code>, <code>scope</code> (<code>org</code>|<code>mine</code>).</p><p>Open = stages that are neither won nor lost. Weighted pipeline sums <code>amount * (probability / 100)</code> for open deals with both fields set. Conversion rate = won / (won + lost) when there is at least one closed (won or lost) deal.</p><h2 id="board" tabindex="-1">Board <a class="header-anchor" href="#board" aria-label="Permalink to &quot;Board&quot;">​</a></h2><h3 id="get-opportunities-board" tabindex="-1">GET <code>/opportunities/board</code> <a class="header-anchor" href="#get-opportunities-board" aria-label="Permalink to &quot;GET `/opportunities/board`&quot;">​</a></h3><p>Same filters as list (minus pagination). Query: <code>per_column</code> (default 50, max 100).</p><p>Returns one column per stage: <code>stage</code>, <code>opportunity_count</code>, <code>total_amount</code>, <code>opportunities</code> (limited list).</p><h2 id="opportunities-crud" tabindex="-1">Opportunities CRUD <a class="header-anchor" href="#opportunities-crud" aria-label="Permalink to &quot;Opportunities CRUD&quot;">​</a></h2><h3 id="get-opportunities" tabindex="-1">GET <code>/opportunities</code> <a class="header-anchor" href="#get-opportunities" aria-label="Permalink to &quot;GET `/opportunities`&quot;">​</a></h3><p>Query: <code>search</code>, <code>stage_id</code>, <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_opportunities</code>, <code>contact_id</code>, <code>company_id</code>, <code>lead_id</code>, <code>trashed</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>stage</code>, assignee/creator refs, related <code>contact</code> / <code>company</code> / <code>lead</code> when loaded, and <code>latest_note</code>.</p><h3 id="post-opportunities" tabindex="-1">POST <code>/opportunities</code> <a class="header-anchor" href="#post-opportunities" aria-label="Permalink to &quot;POST `/opportunities`&quot;">​</a></h3><p>Body: <code>name</code> (required), <code>amount</code>, <code>currency</code> (3-letter, default <code>USD</code>), <code>probability</code> (0–100), <code>expected_close_date</code>, <code>stage_id</code> (defaults to the workspace default stage), <code>contact_id</code>, <code>company_id</code>, <code>lead_id</code>, <code>assigned_to</code>.</p><p>Related FKs are optional. Each FK requires the corresponding module to be entitled when set.</p><h3 id="get-opportunities-id" tabindex="-1">GET <code>/opportunities/{id}</code> <a class="header-anchor" href="#get-opportunities-id" aria-label="Permalink to &quot;GET `/opportunities/{id}`&quot;">​</a></h3><p>Includes stage, assignee, creator, notes, timeline activities, and related refs.</p><h3 id="put-opportunities-id" tabindex="-1">PUT <code>/opportunities/{id}</code> <a class="header-anchor" href="#put-opportunities-id" aria-label="Permalink to &quot;PUT `/opportunities/{id}`&quot;">​</a></h3><p>Partial update.</p><h3 id="delete-opportunities-id" tabindex="-1">DELETE <code>/opportunities/{id}</code> <a class="header-anchor" href="#delete-opportunities-id" aria-label="Permalink to &quot;DELETE `/opportunities/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>opportunities.delete</code>.</p><h3 id="post-opportunities-id-restore" tabindex="-1">POST <code>/opportunities/{id}/restore</code> <a class="header-anchor" href="#post-opportunities-id-restore" aria-label="Permalink to &quot;POST `/opportunities/{id}/restore`&quot;">​</a></h3><p>Permission: <code>opportunities.restore</code>.</p><h3 id="delete-opportunities-id-force" tabindex="-1">DELETE <code>/opportunities/{id}/force</code> <a class="header-anchor" href="#delete-opportunities-id-force" aria-label="Permalink to &quot;DELETE `/opportunities/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted opportunity. Permission: <code>opportunities.force.delete</code>.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-opportunities-id-assign" tabindex="-1">POST <code>/opportunities/{id}/assign</code> <a class="header-anchor" href="#post-opportunities-id-assign" aria-label="Permalink to &quot;POST `/opportunities/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><p>Permission: <code>opportunities.assign</code>.</p><h3 id="post-opportunities-id-stage" tabindex="-1">POST <code>/opportunities/{id}/stage</code> <a class="header-anchor" href="#post-opportunities-id-stage" aria-label="Permalink to &quot;POST `/opportunities/{id}/stage`&quot;">​</a></h3><p><code>{ &quot;stage_id&quot;: number }</code></p><p>Permission: <code>opportunities.update</code>. Records a <code>stage_changed</code> timeline entry.</p><h3 id="post-opportunities-id-notes" tabindex="-1">POST <code>/opportunities/{id}/notes</code> <a class="header-anchor" href="#post-opportunities-id-notes" aria-label="Permalink to &quot;POST `/opportunities/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><p>Permission: <code>opportunities.update</code>.</p><h3 id="get-opportunities-id-timeline" tabindex="-1">GET <code>/opportunities/{id}/timeline</code> <a class="header-anchor" href="#get-opportunities-id-timeline" aria-label="Permalink to &quot;GET `/opportunities/{id}/timeline`&quot;">​</a></h3><p>Domain timeline entries for the deal (<code>created</code>, <code>updated</code>, <code>assigned</code>, <code>stage_changed</code>, <code>note_added</code>, <code>deleted</code>, <code>restored</code>).</p>',45)])])}const m=o(d,[["render",n]]);export{h as __pageData,m as default};
